questions.explanation:
树上每走一步奇偶性翻转，偶数步到达的结点与起点同色。树是二分图，DFS 染色（相邻异色）后统计两色各自结点数，从结点 i 出发的答案即 i 所在颜色的总数。注意可重复经过、可零步结束，故起点自身计入。时间复杂度 O(n)。

参考程序：
```cpp
#include <cstdio>
#include <algorithm>
using namespace std;

const int N = 2e5 + 5;
const int E = N << 1;

int n;
int h[N], to[E], nx[E], et;
int cnt[N], bel[N];

void ae(int u, int v) {
    et++;
    to[et] = v;
    nx[et] = h[u];
    h[u] = et;
}

void dfs(int u, int c, int f) {
    bel[u] = c;
    cnt[c]++;
    for (int i = h[u]; i; i = nx[i])
        if (to[i] != f)
            dfs(to[i], c ^ 1, u);
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i < n; i++) {
        int u, v;
        scanf("%d%d", &u, &v);
        ae(u, v);
        ae(v, u);
    }
    dfs(1, 0, 0);
    for (int i = 1; i <= n; i++)
        printf("%d%c", cnt[bel[i]], " \n"[i == n]);
    return 0;
}
```

环线上不重复经过的行程对应一段非空连续区间（区间长度 ≤ n）。破环为链：把数组复制一份接在后面，问题化为「长度不超过 n 的最大子段和」。用前缀和 + 单调队列：枚举右端点 i，队头维护长度 n 窗口内最小前缀和，答案取 pre[i] − pre[队头]。时间复杂度 O(n)。

参考程序：
```cpp
#include <cstdio>
#include <algorithm>
using namespace std;

const int N = 4e5 + 5;

int n;
long long a[N], pre[N];
int q[N], ql, qr;
long long ans;

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        scanf("%lld", &a[i]);
        a[n + i] = a[i];
    }
    for (int i = 1; i <= 2 * n; i++)
        pre[i] = pre[i - 1] + a[i];
    ql = qr = 1;
    ans = -1e18;
    for (int i = 1; i <= 2 * n; i++) {
        while (ql <= qr && q[ql] < i - n)
            ql++;
        ans = max(ans, pre[i] - pre[q[ql]]);
        while (ql <= qr && pre[i] < pre[q[qr]])
            qr--;
        q[++qr] = i;
    }
    printf("%lld\n", ans);
    return 0;
}
```
